questionvariables.text:
/* Typical trip with no information */
typical: 60;

/* Clue levels and the minutes each adds to the typical trip */
timeL: ["05:30", "08:00", "13:00", "17:30", "19:30", "23:00"];
timeE: [-15, 10, -5, 20, 10, -20];
dayL: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
dayE: [0, 0, 0, 0, 10, -5, -5];
areaL: ["CBD", "Westlands", "Kilimani", "Karen", "Ruaka", "Embakasi"];
areaE: [10, 5, 0, 5, 10, -10];
wxL: ["Dry", "Light rain", "Heavy rain"];
wxE: [0, 5, 15];
newsL: ["No incidents", "Lorry stuck on Mombasa Rd", "Roadworks on Ngong Rd", "Crash on Uhuru Highway"];
newsE: [0, 20, 20, 20];
rateL: ["4.6 stars", "4.7 stars", "4.8 stars", "4.9 stars"];

/* Random trip: weighted so incidents and heavy rain are less common */
ti: rand(6) + 1;
di: rand(7) + 1;
ai: rand(6) + 1;
wi: rand([1, 1, 1, 2, 3]);
ni: rand([1, 1, 1, 1, 1, 1, 2, 3, 4]);
ri: rand(4) + 1;
noise: rand_with_step(-5, 5, 1);

cardn: ["Time of day", "Day", "Pickup point", "Weather", "Traffic news", "Driver rating"];
cardv: [timeL[ti], dayL[di], areaL[ai], wxL[wi], newsL[ni], rateL[ri]];
eff: [timeE[ti], dayE[di], areaE[ai], wxE[wi], newsE[ni], 0];
actual: typical + apply("+", eff) + noise;

/* Signed strings for display, e.g. "+10", "-5", "0" */
sgnS: lambda([x], if x > 0 then sconcat("+", x) else if x < 0 then sconcat("-", -x) else "0");
Es: map(sgnS, eff);
noiseS: sgnS(noise);

/* Teacher's answers: time of day and traffic news are the most informative pair */
ta1: [1, 5];
ta2: typical + eff[1] + eff[5];
ta3: actual + 10;

feedbackvariables.text:
sel: if listp(ans1) then ans1 else [];
sel: unique(sublist(sel, lambda([x], integerp(x) and x >= 1 and x <= 6)));
accMin: apply("+", cons(0, map(lambda([k], eff[k]), sel)));
pred: typical + accMin;
accS: sgnS(accMin);

sel: if listp(ans1) then ans1 else [];
sel: unique(sublist(sel, lambda([x], integerp(x) and x >= 1 and x <= 6)));
hid: sublist([1, 2, 3, 4, 5, 6], lambda([k], not member(k, sel)));
accMin: apply("+", cons(0, map(lambda([k], eff[k]), sel)));
unaccMin: apply("+", cons(0, map(lambda([k], eff[k]), hid)));
pred: typical + accMin;
accS: sgnS(accMin);
unaccS: sgnS(unaccMin);
wait: ans3 - actual;
late: actual - ans3;
hidAbs: map(lambda([k], abs(eff[k])), hid);
big: if hid = [] then 0 else (if lmax(hidAbs) = 0 then 0 else hid[first(sublist_indices(hidAbs, lambda([x], x = lmax(hidAbs))))]);
